import attr
from enum import Enum, unique
from typing import List, Optional


@unique
class PDPTypes(Enum):
    X_25 = 'X.25'
    IP = 'IP'
    IPV6 = 'IPV6'
    IPV4V6 = 'IPV4V6'
    OSPIH = 'OSPIH'
    PPP = 'PPP'
    NON_IP = 'Non-IP'
    ETHERNET = 'Ethernet'
    UNSTRUCTURED = 'Unstructured'


@attr.s(cmp=False)
class PDN(object):
    """
    :param str pdp_type: PDP type
    :param str apn: apn string, e.g. wap1.nokia.com
    """
    pdp_type = attr.ib(type=str)
    apn = attr.ib(type=str)


@attr.s(cmp=False)
class PDNAndroidDetails(object):
    r"""
    :param str entryName: MANDATORY it defines name under which its stored on UE e.g. 'ap1.wroc'
    :param str apn: MANDATORY its the apn address e.g. 'ap1.wroc'
    :param list apnType: MANDATORY it tells Android what type of APN it is e.g. [DEFAULT, MMS, XCAP]
    :param Optional[str] authType: Sets authentication type of the APN e.g. 'NONE, PAP, CHAP, PAP'
    :param Optional[str] mcc: Sets MCC of APN e.g. '555'
    :param Optional[str] mnc: Sets MNC od APN e.g. '10'
    :param Optional[bool] carrierEnabled: Sets current status of APN
    :param Optional[str] operatorNumeric: Sets the numeric operator ID for the APN e.g. '55510'
    :param Optional[str] protocol: Sets the protocol to use to connect to this APN e.g. 'IPV4V6', one of: IP, IPV6,
                                                                                         IPV4V6, PPP
    :param Optional[str] roamingProtocol: Sets the protocol to use to connect to this APN when the device is roaming
                                                                                                        e.g. 'IPV4V6'
    :param Optional[str] proxyAddress: HTTP proxy for the APN
    :param Optional[int] proxyPort: proxy port of the APN
    :param Optional[str] mmsc: MMSC Uri of the APN
    :param Optional[str] mmsProxyAdderss: MMS proxy for the APN
    :param Optional[int] mmsProxyPort: MMS proxy port of the APN
    :param Optional[str] user: APN username of the APN
    :param Optional[str] password: APN password of the APN
    :param Optional[str] mvnoType: MVNO match type for this APN. Can be one of: SPN, IMSI, GID, ICCID
    :param Optional[str] networkType: Radio Technology (Network Type) info for this APN.
    Can be one of xRTT, CDMA, EDGE,EHRDP, EVDO\_,EVDO\_A, EVDO\_B, GPRS, GSM, HSDPA, HSPA, HSPAP, HSUPA, IDEN, IWLAN, LTE,
    NR, TDSCDMA, UMTS
    """
    entryName = attr.ib(type=str)
    apn = attr.ib(type=str)
    apnType = attr.ib(type=List[str])
    authType = attr.ib(default="", type=Optional[str])
    mcc = attr.ib(default="", type=Optional[str])
    mnc = attr.ib(default="", type=Optional[str])
    carrierEnabled = attr.ib(default=False, type=Optional[bool])
    operatorNumeric = attr.ib(default="", type=Optional[str])
    protocol = attr.ib(default="", type=Optional[str])
    roamingProtocol = attr.ib(default="", type=Optional[str])
    proxyAddress = attr.ib(default="", type=Optional[str])
    proxyPort = attr.ib(default=None, type=Optional[int])
    mmsc = attr.ib(default="", type=Optional[str])
    mmsProxyAdderss = attr.ib(default="", type=Optional[str])
    mmsProxyPort = attr.ib(default=None, type=Optional[int])
    user = attr.ib(default="", type=Optional[str])
    password = attr.ib(default="", type=Optional[str])
    mvnoType = attr.ib(default="", type=Optional[str])
    networkType = attr.ib(default="", type=Optional[str])


